BEGIN READ ONLY; SET LOCAL statement_timeout='2000ms';
SELECT jsonb_build_object(
'cron_recent',(SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT jobid,status,count(*) n,round(avg(extract(epoch FROM(end_time-start_time)))*1000,3) avg_ms,round(max(extract(epoch FROM(end_time-start_time)))*1000,3) max_ms,min(start_time) first_run,max(start_time) last_run,count(*) FILTER(WHERE strpos(lower(return_message),'timeout')>0) timeout_messages FROM(SELECT jobid,status,start_time,end_time,return_message FROM cron.job_run_details ORDER BY runid DESC LIMIT 160)r GROUP BY jobid,status)x),
'searching_sample',(SELECT count(*) FROM(SELECT id FROM public.orders WHERE order_status IN('created','searching') LIMIT 21)s),
'stale_running_searching_sample',(SELECT count(*) FROM(SELECT id FROM public.orders WHERE order_status IN('created','searching') AND dispatch_worker_running IS TRUE AND dispatch_worker_started_at<now()-interval'5 minutes' LIMIT 21)s),
'rls_helper_definition',(SELECT pg_get_functiondef('public.is_admin()'::regprocedure)),
'observed_at',clock_timestamp()) AS status;
COMMIT;
